#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Reads .env.test to get required environment variable keys and validates
 * that each key has a value set in the current environment.
 */

const fs = require('fs');
const path = require('path');

const ENV_TEST_PATH = path.join(__dirname, '.env.test');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const requiredKeys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (match) {
      requiredKeys.push(match[1]);
    }
  }

  return requiredKeys;
}

function validateEnvironment(requiredKeys) {
  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
    } else if (value.trim() === '') {
      empty.push(key);
    }
  }

  return { missing, empty };
}

function main() {
  console.log('Pre-deployment environment validation');
  console.log('=====================================\n');

  // Check if .env.test exists
  if (!fs.existsSync(ENV_TEST_PATH)) {
    console.error(`Error: ${ENV_TEST_PATH} not found`);
    process.exit(1);
  }

  // Parse required keys from .env.test
  const requiredKeys = parseEnvFile(ENV_TEST_PATH);

  if (requiredKeys.length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables:\n`);

  // Validate each key
  const { missing, empty } = validateEnvironment(requiredKeys);

  // Report results
  for (const key of requiredKeys) {
    if (missing.includes(key)) {
      console.log(`  [MISSING] ${key}`);
    } else if (empty.includes(key)) {
      console.log(`  [EMPTY]   ${key}`);
    } else {
      console.log(`  [OK]      ${key}`);
    }
  }

  console.log('');

  // Exit with appropriate code
  const hasErrors = missing.length > 0 || empty.length > 0;

  if (hasErrors) {
    console.error('Validation FAILED:');
    if (missing.length > 0) {
      console.error(`  - ${missing.length} variable(s) not set: ${missing.join(', ')}`);
    }
    if (empty.length > 0) {
      console.error(`  - ${empty.length} variable(s) empty: ${empty.join(', ')}`);
    }
    console.error('\nPlease set all required environment variables before deployment.');
    process.exit(1);
  }

  console.log('Validation PASSED: All required environment variables are set.');
  process.exit(0);
}

main();

