#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Reads .env.test to get required environment variable keys and validates
 * that each key has a value set in the current environment.
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = path.join(__dirname, '.env.test');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const keys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (match) {
      keys.push(match[1]);
    }
  }

  return keys;
}

function validateEnvironment() {
  console.log('Pre-deployment environment validation');
  console.log('=====================================\n');

  // Check if .env.test exists
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Error: ${ENV_FILE} not found`);
    process.exit(1);
  }

  // Parse required keys from .env.test
  const requiredKeys = parseEnvFile(ENV_FILE);

  if (requiredKeys.length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables:\n`);

  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      console.log(`  [MISSING] ${key}`);
      missing.push(key);
    } else if (value === '') {
      console.log(`  [EMPTY]   ${key}`);
      empty.push(key);
    } else {
      console.log(`  [OK]      ${key}`);
    }
  }

  console.log('\n-------------------------------------');

  const hasErrors = missing.length > 0 || empty.length > 0;

  if (hasErrors) {
    console.log('\nValidation FAILED\n');

    if (missing.length > 0) {
      console.log(`Missing variables (${missing.length}):`);
      missing.forEach(key => console.log(`  - ${key}`));
    }

    if (empty.length > 0) {
      console.log(`\nEmpty variables (${empty.length}):`);
      empty.forEach(key => console.log(`  - ${key}`));
    }

    console.log('\nPlease set all required environment variables before deployment.');
    process.exit(1);
  }

  console.log('\nValidation PASSED');
  console.log('All required environment variables are set.');
  process.exit(0);
}

validateEnvironment();

