#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Confirms all required environment variables are set by reading .env.test
 * and checking each key has a value in the current environment.
 */

const fs = require('fs');
const path = require('path');

const ENV_TEST_PATH = path.join(__dirname, '..', '.env.test');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const keys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key (everything before the first =)
    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      keys.push(match[1]);
    }
  }

  return keys;
}

function validateEnvironment() {
  console.log('Pre-deployment environment validation');
  console.log('=====================================\n');

  // Check if .env.test exists
  if (!fs.existsSync(ENV_TEST_PATH)) {
    console.error(`Error: ${ENV_TEST_PATH} not found`);
    process.exit(1);
  }

  // Parse required keys from .env.test
  const requiredKeys = parseEnvFile(ENV_TEST_PATH);

  if (requiredKeys.length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables...\n`);

  const missing = [];
  const empty = [];
  const valid = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
    } else if (value.trim() === '') {
      empty.push(key);
    } else {
      valid.push(key);
    }
  }

  // Report results
  for (const key of valid) {
    console.log(`  [OK] ${key}`);
  }

  for (const key of empty) {
    console.log(`  [EMPTY] ${key}`);
  }

  for (const key of missing) {
    console.log(`  [MISSING] ${key}`);
  }

  console.log('');

  // Summary
  const hasErrors = missing.length > 0 || empty.length > 0;

  if (hasErrors) {
    console.log('Validation FAILED');
    console.log(`  Valid: ${valid.length}`);
    console.log(`  Empty: ${empty.length}`);
    console.log(`  Missing: ${missing.length}`);
    process.exit(1);
  }

  console.log(`Validation PASSED - all ${valid.length} environment variables are set`);
  process.exit(0);
}

validateEnvironment();

