#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Reads .env.test and confirms all required environment variables are set
 */

const fs = require('fs');
const path = require('path');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const keys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key (everything before the first '=')
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/i);
    if (match) {
      keys.push(match[1]);
    }
  }

  return keys;
}

function validateEnvironment(requiredKeys) {
  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
    } else if (value.trim() === '') {
      empty.push(key);
    }
  }

  return { missing, empty };
}

function main() {
  const envTestPath = path.resolve(__dirname, '..', '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found at', envTestPath);
    process.exit(1);
  }

  console.log('Reading required environment variables from .env.test...\n');

  // Parse required keys from .env.test
  const requiredKeys = parseEnvFile(envTestPath);

  if (requiredKeys.length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(0);
  }

  console.log(`Found ${requiredKeys.length} required environment variable(s):`);
  requiredKeys.forEach(key => console.log(`  - ${key}`));
  console.log();

  // Validate current environment
  const { missing, empty } = validateEnvironment(requiredKeys);

  // Report results
  if (missing.length === 0 && empty.length === 0) {
    console.log('All required environment variables are set.\n');
    console.log('Pre-deployment validation PASSED');
    process.exit(0);
  }

  // Report issues
  if (missing.length > 0) {
    console.error(`\nMissing environment variables (${missing.length}):`);
    missing.forEach(key => console.error(`  - ${key}`));
  }

  if (empty.length > 0) {
    console.error(`\nEmpty environment variables (${empty.length}):`);
    empty.forEach(key => console.error(`  - ${key}`));
  }

  console.error('\nPre-deployment validation FAILED');
  process.exit(1);
}

main();

