#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Confirms all required environment variables from .env.test are set
 */

const fs = require('fs');
const path = require('path');

function validateEnvironment() {
  const envTestPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  // Read and parse .env.test
  const envTestContent = fs.readFileSync(envTestPath, 'utf-8');
  const lines = envTestContent.split('\n');

  const requiredKeys = [];
  const missingKeys = [];
  const emptyKeys = [];

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    // Extract the key (everything before the first =)
    const equalsIndex = trimmedLine.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmedLine.substring(0, equalsIndex).trim();
    if (!key) {
      continue;
    }

    requiredKeys.push(key);

    // Check if the environment variable is set
    const value = process.env[key];

    if (value === undefined) {
      missingKeys.push(key);
    } else if (value === '') {
      emptyKeys.push(key);
    }
  }

  // Report results
  console.log('Pre-deployment Environment Validation');
  console.log('=====================================\n');
  console.log(`Checking ${requiredKeys.length} required environment variables...\n`);

  if (missingKeys.length === 0 && emptyKeys.length === 0) {
    console.log('All required environment variables are set.\n');
    console.log('Validated keys:');
    requiredKeys.forEach(key => console.log(`  - ${key}`));
    console.log('\nValidation passed.');
    process.exit(0);
  }

  // Report issues
  if (missingKeys.length > 0) {
    console.error('Missing environment variables:');
    missingKeys.forEach(key => console.error(`  - ${key}`));
    console.error('');
  }

  if (emptyKeys.length > 0) {
    console.error('Empty environment variables (set but no value):');
    emptyKeys.forEach(key => console.error(`  - ${key}`));
    console.error('');
  }

  const totalIssues = missingKeys.length + emptyKeys.length;
  console.error(`Validation failed: ${totalIssues} issue(s) found.`);
  console.error('Please set all required environment variables before deployment.');
  process.exit(1);
}

validateEnvironment();

