 * Reads .env.test and confirms all required environment variables are set
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = path.join(__dirname, '.env.test');

function validateEnvironment() {
  // Read the .env.test file
  let envContent;
  try {
    envContent = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    console.error(`Error: Could not read ${ENV_FILE}`);
    console.error(err.message);
    process.exit(1);
  }

  // Parse environment variable keys (skip comments and empty lines)
  const requiredKeys = envContent
    .split('\n')
    .filter(line => line.trim() && !line.trim().startsWith('#'))
    .map(line => line.split('=')[0].trim())
    .filter(key => key.length > 0);

  if (requiredKeys.length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(0);
  }

  console.log('Validating required environment variables...\n');

  const missing = [];
  const present = [];

  for (const key of requiredKeys) {
    const value = process.env[key];
    if (value === undefined || value === '') {
      missing.push(key);
    } else {
      present.push(key);
    }
  }

  // Report results
  if (present.length > 0) {
    console.log(`Present (${present.length}):`);
    present.forEach(key => console.log(`  - ${key}`));
    console.log();
  }

  if (missing.length > 0) {
    console.error(`Missing (${missing.length}):`);
    missing.forEach(key => console.error(`  - ${key}`));
    console.error('\nPre-deployment validation FAILED');
    console.error('Please set all required environment variables before deploying.');
    process.exit(1);
  }

  console.log('Pre-deployment validation PASSED');
  console.log(`All ${requiredKeys.length} required environment variables are set.`);
  process.exit(0);
}

validateEnvironment();

