#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Confirms all required environment variables from .env.test are set
 */

const fs = require('fs');
const path = require('path');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const requiredKeys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Parse KEY=value format
    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      requiredKeys.push(match[1]);
    }
  }

  return requiredKeys;
}

function validateEnvironment(requiredKeys) {
  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
    } else if (value.trim() === '') {
      empty.push(key);
    }
  }

  return { missing, empty };
}

function main() {
  const envTestPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  console.log('Pre-deployment environment validation');
  console.log('======================================\n');

  const requiredKeys = parseEnvFile(envTestPath);

  if (requiredKeys.length === 0) {
    console.log('No environment variables defined in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables...\n`);

  const { missing, empty } = validateEnvironment(requiredKeys);

  // Report results
  let hasErrors = false;

  if (missing.length > 0) {
    hasErrors = true;
    console.error('Missing environment variables:');
    for (const key of missing) {
      console.error(`  - ${key}`);
    }
    console.error('');
  }

  if (empty.length > 0) {
    hasErrors = true;
    console.error('Empty environment variables:');
    for (const key of empty) {
      console.error(`  - ${key}`);
    }
    console.error('');
  }

  if (hasErrors) {
    console.error('Validation FAILED: Please set all required environment variables before deployment.');
    process.exit(1);
  }

  console.log('All required environment variables are set.');
  console.log('Validation PASSED');
  process.exit(0);
}

main();

