#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Reads .env.test to get required environment variable keys
 * and confirms each one has a value set in the current environment.
 */

const fs = require('fs');
const path = require('path');

function validateEnvironment() {
  const envTestPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  // Read and parse .env.test
  const content = fs.readFileSync(envTestPath, 'utf-8');
  const lines = content.split('\n');

  const requiredKeys = [];
  const missingKeys = [];
  const emptyKeys = [];

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/i);
    if (match) {
      const key = match[1];
      requiredKeys.push(key);

      // Check if the key exists in the current environment
      const value = process.env[key];
      if (value === undefined) {
        missingKeys.push(key);
      } else if (value === '') {
        emptyKeys.push(key);
      }
    }
  }

  // Report results
  console.log('Pre-deployment Environment Validation');
  console.log('=====================================\n');
  console.log(`Required environment variables: ${requiredKeys.length}`);
  console.log(`  ${requiredKeys.join(', ')}\n`);

  let hasErrors = false;

  if (missingKeys.length > 0) {
    console.error(`Missing environment variables (${missingKeys.length}):`);
    for (const key of missingKeys) {
      console.error(`  - ${key}`);
    }
    console.error('');
    hasErrors = true;
  }

  if (emptyKeys.length > 0) {
    console.error(`Empty environment variables (${emptyKeys.length}):`);
    for (const key of emptyKeys) {
      console.error(`  - ${key}`);
    }
    console.error('');
    hasErrors = true;
  }

  if (hasErrors) {
    console.error('Validation FAILED: Please set all required environment variables before deployment.');
    process.exit(1);
  }

  console.log('Validation PASSED: All required environment variables are set.');
  process.exit(0);
}

validateEnvironment();

