#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Confirms all required environment variables from .env.test are set
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = path.join(__dirname, '..', '.env.test');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const requiredKeys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (match) {
      requiredKeys.push(match[1]);
    }
  }

  return requiredKeys;
}

function validateEnvironment(requiredKeys) {
  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    if (!(key in process.env)) {
      missing.push(key);
    } else if (process.env[key] === '') {
      empty.push(key);
    }
  }

  return { missing, empty };
}

function main() {
  console.log('Pre-deployment environment validation');
  console.log('======================================\n');

  // Check if .env.test exists
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Error: ${ENV_FILE} not found`);
    process.exit(1);
  }

  // Parse required keys from .env.test
  const requiredKeys = parseEnvFile(ENV_FILE);

  if (requiredKeys.length === 0) {
    console.log('No environment variables defined in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables...\n`);

  // Validate each key is set
  const { missing, empty } = validateEnvironment(requiredKeys);

  // Report results
  const valid = requiredKeys.filter(k => !missing.includes(k) && !empty.includes(k));

  for (const key of valid) {
    console.log(`  [OK] ${key}`);
  }

  for (const key of empty) {
    console.log(`  [EMPTY] ${key}`);
  }

  for (const key of missing) {
    console.log(`  [MISSING] ${key}`);
  }

  console.log('');

  // Exit with error if any validation failed
  if (missing.length > 0 || empty.length > 0) {
    console.error('Validation FAILED:');
    if (missing.length > 0) {
      console.error(`  - ${missing.length} variable(s) not set: ${missing.join(', ')}`);
    }
    if (empty.length > 0) {
      console.error(`  - ${empty.length} variable(s) empty: ${empty.join(', ')}`);
    }
    process.exit(1);
  }

  console.log('Validation PASSED: All required environment variables are set.');
  process.exit(0);
}

main();

