#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Reads .env.test to determine required environment variables,
 * then confirms each key has a value in the current environment.
 */

const fs = require('fs');
const path = require('path');

const ENV_TEST_PATH = path.join(__dirname, '..', '.env.test');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const keys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key (everything before the first '=')
    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex > 0) {
      const key = trimmed.substring(0, equalsIndex).trim();
      keys.push(key);
    }
  }

  return keys;
}

function validateEnvironment() {
  console.log('Pre-deployment environment validation\n');
  console.log(`Reading required variables from: ${ENV_TEST_PATH}\n`);

  if (!fs.existsSync(ENV_TEST_PATH)) {
    console.error(`Error: ${ENV_TEST_PATH} not found`);
    process.exit(1);
  }

  const requiredKeys = parseEnvFile(ENV_TEST_PATH);

  if (requiredKeys.length === 0) {
    console.log('No environment variables defined in .env.test');
    process.exit(0);
  }

  console.log(`Checking ${requiredKeys.length} required environment variables:\n`);

  const missing = [];
  const empty = [];
  const valid = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
      console.log(`  [MISSING] ${key}`);
    } else if (value === '') {
      empty.push(key);
      console.log(`  [EMPTY]   ${key}`);
    } else {
      valid.push(key);
      console.log(`  [OK]      ${key}`);
    }
  }

  console.log('\n--- Summary ---');
  console.log(`Valid:   ${valid.length}`);
  console.log(`Missing: ${missing.length}`);
  console.log(`Empty:   ${empty.length}`);

  if (missing.length > 0 || empty.length > 0) {
    console.log('\nValidation FAILED');
    console.log('\nThe following environment variables must be set before deployment:');

    if (missing.length > 0) {
      console.log('\nMissing:');
      missing.forEach(key => console.log(`  - ${key}`));
    }

    if (empty.length > 0) {
      console.log('\nEmpty (set but no value):');
      empty.forEach(key => console.log(`  - ${key}`));
    }

    process.exit(1);
  }

  console.log('\nValidation PASSED - all required environment variables are set');
  process.exit(0);
}

validateEnvironment();

