#!/usr/bin/env node

/**
 * Pre-deployment validation script
 * Confirms all required environment variables from .env.test are set
 */

const fs = require('fs');
const path = require('path');

function validateEnvironment() {
  const envTestPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  const content = fs.readFileSync(envTestPath, 'utf-8');
  const lines = content.split('\n');

  const requiredKeys = [];
  const missingKeys = [];
  const emptyKeys = [];

  // Parse .env.test to extract required variable names
  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (match) {
      requiredKeys.push(match[1]);
    }
  }

  // Check each required key in the current environment
  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missingKeys.push(key);
    } else if (value.trim() === '') {
      emptyKeys.push(key);
    }
  }

  // Report results
  console.log('Pre-deployment Environment Validation');
  console.log('======================================');
  console.log(`Checking ${requiredKeys.length} required environment variables...\n`);

  if (missingKeys.length === 0 && emptyKeys.length === 0) {
    console.log('All required environment variables are set.');
    process.exit(0);
  }

  if (missingKeys.length > 0) {
    console.error('Missing environment variables:');
    for (const key of missingKeys) {
      console.error(`  - ${key}`);
    }
    console.error('');
  }

  if (emptyKeys.length > 0) {
    console.error('Empty environment variables:');
    for (const key of emptyKeys) {
      console.error(`  - ${key}`);
    }
    console.error('');
  }

  console.error('Deployment validation failed. Please set all required environment variables.');
  process.exit(1);
}

validateEnvironment();
